insert into onb_screens (id, sort, kind, title_de, title_en, short_de, short_en, intro_de, intro_en, active) values
  ('project', 10, 'questions', 'Ihr Projekt', 'Your project', 'Projekt', 'Project', 'Zuerst ein paar Angaben zu Ihnen und zum gebuchten Paket. Ihre Antworten werden automatisch gespeichert – Sie können jederzeit unterbrechen und über Ihren Link weitermachen.', 'A few details about you and the package you booked first. Your answers save automatically — you can stop at any time and pick up again from your link.', true),
  ('business', 20, 'questions', 'Unternehmensdaten', 'Business details', 'Unternehmen', 'Business', 'Diese Angaben landen auf Ihren Rechtsseiten und müssen exakt stimmen. Bitte prüfen Sie sie, statt sie von Ihrer alten Website zu kopieren – die meisten Fehler, die wir finden, wurden von einer früheren Seite übernommen.', 'These go on your legal pages, so they have to be exact. Please check them rather than copying from your old website — most of the errors we find came across from a previous site.', true),
  ('inboxes', 30, 'questions', 'Postfächer und Benachrichtigungen', 'Inboxes and notifications', 'Postfächer', 'Inboxes', 'Wer soll erreichbar sein – und wer erfährt es, wenn über die Website etwas eingeht?', 'Who should be reachable — and who hears about it when something arrives through the site?', true),
  ('design', 40, 'questions', 'Gestaltungsrichtung', 'Design direction', 'Design', 'Design', 'Es gibt hier kein Richtig oder Falsch. Je klarer Sie sagen, was Ihnen gefällt und was nicht, desto näher liegt der erste Entwurf an Ihrer Vorstellung.', 'There''s no right or wrong here. The clearer you are about what you like and don''t, the closer the first draft lands to what you had in mind.', true),
  ('pages', 50, 'questions', 'Seitenstruktur', 'Page structure', 'Seiten', 'Pages', 'Welche Seiten braucht Ihre Website, was bieten Sie an – und was soll ein Besucher tun?', 'Which pages does your site need, what do you offer — and what should a visitor do?', true),
  ('integrations', 60, 'questions', 'Verbundene Systeme', 'Integrations and connected systems', 'Systeme', 'Systems', 'Alles, womit die Website verbunden sein soll: Karten, Bewertungen, Buchung, Zahlung, Newsletter, CRM.', 'Everything the site should connect to: maps, reviews, booking, payments, newsletter, CRM.', true),
  ('files', 70, 'questions', 'Logo, Fotos und Dateien', 'Logo, photos and files', 'Dateien', 'Files', 'Ein Ordnerlink reicht. Alternativ können Sie hier einige Dateien direkt hochladen – ohne Anmeldung.', 'A folder link is enough. Or upload a handful of files right here — no sign-in needed.', true),
  ('access_legal', 80, 'questions', 'Zugänge und Rechtliches', 'Access and legal', 'Zugänge & Recht', 'Access & legal', 'Bitte nur Namen und Zuständigkeiten – niemals Passwörter. Zugangsdaten tauschen wir später über einen sicheren Weg aus.', 'Names and responsibilities only — never passwords. We exchange credentials later through a secure channel.', true),
  ('timing', 90, 'questions', 'Zeitplan', 'Timing', 'Zeitplan', 'Timing', 'Wann soll die Website live gehen – und bis wann können Sie liefern?', 'When should the site go live — and by when can you deliver?', true),
  ('review', 100, 'review', 'Prüfen und bestätigen', 'Review and confirm', 'Abschluss', 'Review', null, null, true)
on conflict (id) do nothing;

