  ('factual_claims', 'business', 150, 'textarea', 'Welche Fakten sollen auf der Website stehen?', 'What factual claims should appear on your site?', 'Jahre am Markt, Anzahl Kunden, Reaktionszeiten, Zertifizierungen, Auszeichnungen, Mitgliedschaften.', 'Years in business, number of clients, reply times, certifications, awards, memberships.', null, null, false, false, false, '[]'::jsonb, '{"rows":4}'::jsonb, '[]'::jsonb, true),
