  ('private_content', 'business', 180, 'radio', 'Gibt es Inhalte, die hinter einem Passwort- oder Mitgliederbereich liegen sollen?', 'Is there information that should sit behind a password-protected or member page?', null, null, null, null, false, false, false, '[{"value":"yes","label_de":"Ja","label_en":"Yes"},{"value":"no","label_de":"Nein","label_en":"No"},{"value":"unsure","label_de":"Nicht sicher","label_en":"Not sure"}]'::jsonb, '{}'::jsonb, '[]'::jsonb, true),
  ('private_content_detail', 'business', 190, 'textarea', 'Was soll dort liegen – und wer bekommt Zugang?', 'What should sit behind it, and who gets access?', 'Mitgliederbereiche sind nicht Teil des gebuchten Pakets – wir melden uns dazu separat bei Ihnen.', 'Member areas are not part of the booked package — we''ll come back to you on this separately.', null, null, true, false, false, '[]'::jsonb, '{"rows":3}'::jsonb, '[{"key":"private_content","values":["yes"]}]'::jsonb, true),
  ('site_emails', 'inboxes', 10, 'textarea', 'Welche E-Mail-Adressen sollen auf der Website erscheinen?', 'Which email addresses should appear on the site?', 'Nur Adressen, die tatsächlich jemand liest.', 'Only addresses someone actually reads.', null, null, true, false, false, '[]'::jsonb, '{"rows":3}'::jsonb, '[]'::jsonb, true),
  ('notification_routing', 'inboxes', 20, 'repeater', 'Wenn etwas eingeht – wer soll davon erfahren?', 'When something arrives, who should hear about it?', 'Eine Regel pro Zeile. Sie können verschiedene Dinge an verschiedene Personen schicken.', 'One rule per line — you can send different things to different people.', null, null, true, false, false, '[]'::jsonb, '{"initial_rows":2,"min_rows":1,"max_rows":8,"add_label_de":"Weitere Regel","add_label_en":"Add another","fields":[{"key":"trigger","type":"select","label_de":"Wenn eingeht …","label_en":"When this arrives …","required":true,"options":[{"value":"enquiry","label_de":"Kontaktanfrage","label_en":"Enquiry"},{"value":"booking","label_de":"Terminbuchung","label_en":"Booking"},{"value":"callback","label_de":"Rückrufwunsch","label_en":"Callback request"},{"value":"newsletter","label_de":"Newsletter-Anmeldung","label_en":"Newsletter sign-up"},{"value":"order","label_de":"Bestellung","label_en":"Order"},{"value":"other","label_de":"Sonstiges","label_en":"Other"}]},{"key":"email","type":"email","label_de":"… geht an","label_en":"… goes to","required":true,"placeholder_de":"name@firma.de","placeholder_en":"name@company.com"}]}'::jsonb, '[]'::jsonb, true),
  ('approver', 'inboxes', 30, 'text', 'Wer gibt die finale Freigabe für die Website?', 'Who gives final approval on the website?', null, null, null, null, true, false, false, '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, true),
  ('content_sender', 'inboxes', 40, 'text', 'Wer schickt uns Texte und Fotos?', 'Who sends us text and photos?', null, null, null, null, true, false, false, '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, true),
  ('site_manager', 'inboxes', 50, 'textarea', 'Wer betreut die Website nach dem Start aktiv in Ihrem Unternehmen?', 'Who will be actively managing the site in the business after launch?', null, null, null, null, false, false, false, '[]'::jsonb, '{"rows":2}'::jsonb, '[]'::jsonb, true),
  ('tone_scale', 'design', 10, 'slider', 'Wie soll sich die Website anfühlen?', 'How should the site feel?', null, null, null, null, true, false, false, '[]'::jsonb, '{"min":1,"max":5,"captions":[{"de":"Verspielt und locker","en":"Fun and playful"},{"de":"Warm und persönlich","en":"Warm and informal"},{"de":"Freundlich, aber professionell","en":"Friendly but professional"},{"de":"Professionell und zurückhaltend","en":"Professional and restrained"},{"de":"Formell und seriös","en":"Formal and serious"}],"examples":[{"de":"Kindergarten, Kreativwerkstatt, Trampolinpark","en":"Kindergarten, art and craft studio, trampoline park"},{"de":"Friseur, Café, Personal Trainer","en":"Hairdresser, café, personal trainer"},{"de":"Die meisten Handwerksbetriebe und Praxen","en":"Most trades, most clinics"},{"de":"Beratung, Arztpraxis","en":"Consultancy, medical practice"},{"de":"Kanzlei, Steuerberatung, Behörde","en":"Law firm, accountant, government"}]}'::jsonb, '[]'::jsonb, true),
  ('personality_scale', 'design', 20, 'slider', 'Wie viel Persönlichkeit?', 'How much personality?', null, null, null, null, true, false, false, '[]'::jsonb, '{"min":1,"max":5,"captions":[{"de":"Sehr zurückgenommen – die Inhalte sprechen","en":"Very restrained — let the content speak"},{"de":"Dezent","en":"Understated"},{"de":"Ausgewogen","en":"Balanced"},{"de":"Mit eigenem Charakter","en":"Distinctive"},{"de":"Mutig und ausdrucksstark","en":"Bold and expressive"}],"examples":[{"de":"Klare Struktur, wenig Schmuck","en":"Clean structure, little decoration"},{"de":"Ruhige Farben, klassische Schrift","en":"Calm colours, classic type"},{"de":"Ein paar Akzente, ohne laut zu werden","en":"A few accents without shouting"},{"de":"Eigene Bildsprache, markante Schrift","en":"Own imagery, distinctive type"},{"de":"Große Gesten, starke Farben","en":"Big gestures, strong colours"}]}'::jsonb, '[]'::jsonb, true),
  ('references', 'design', 30, 'repeater', 'Referenz-Websites', 'Reference websites', 'Link, was Ihnen daran gefällt – und was nicht. Eine Referenz reicht, bis zu drei sind möglich.', 'Link, what you like, what you don''t. One is enough, up to three are welcome.', null, null, true, false, false, '[]'::jsonb, '{"initial_rows":1,"min_rows":1,"max_rows":3,"add_label_de":"Weitere Referenz","add_label_en":"Add another","link_setting":"onb_examples_url","link_label_de":"Beispiele aus unserer Arbeit ansehen","link_label_en":"See examples of our work","fields":[{"key":"url","type":"url","label_de":"Link","label_en":"Link","required":true,"placeholder_de":"https://…","placeholder_en":"https://…"},{"key":"likes","type":"textarea","label_de":"Was gefällt Ihnen daran?","label_en":"What do you like about it?","required":true,"min_chars":15,"placeholder_de":"Aufbau, Farben, Bildsprache, Tonfall …","placeholder_en":"Layout, colours, imagery, tone of voice …"},{"key":"dislikes","type":"textarea","label_de":"Was gefällt Ihnen nicht?","label_en":"What don''t you like?"}]}'::jsonb, '[]'::jsonb, true),
