  ('photo_source', 'files', 60, 'radio', 'Woher kommen Ihre Fotos?', 'Where do your photos come from?', null, null, null, null, false, false, false, '[{"value":"own","label_de":"Eigene Fotos","label_en":"Our own photos"},{"value":"shoot","label_de":"Ein Fotoshooting ist geplant","label_en":"A photo shoot is planned"},{"value":"stock","label_de":"Stockfotos","label_en":"Stock photos"},{"value":"portal","label_de":"Aus einem Lieferanten- oder Herstellerportal","label_en":"From a supplier portal"}]'::jsonb, '{}'::jsonb, '[]'::jsonb, true),
