  ('domain', 'access_legal', 20, 'text', 'Welche Domain soll die Website nutzen?', 'Which domain should the site use?', 'Ihre Webadresse, z. B. www.meine-firma.de. Meistens ändert sich daran nichts.', 'Your web address, e.g. www.my-company.de. Usually this doesn''t change.', 'www.meine-firma.de', 'www.my-company.de', true, false, false, '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, true),
  ('legal_pages', 'access_legal', 30, 'radio', 'Ihre Rechtsseiten – Impressum und Datenschutzerklärung', 'Your legal pages — Impressum and privacy policy', null, null, null, null, true, false, true, '[{"value":"reuse","label_de":"Vorhandene übernehmen","label_en":"Reuse the existing ones"},{"value":"none","label_de":"Wir haben keine","label_en":"We don''t have any"},{"value":"unsure","label_de":"Nicht sicher","label_en":"Not sure"}]'::jsonb, '{}'::jsonb, '[]'::jsonb, true),
