  ('legal_reviewer', 'access_legal', 50, 'text', 'Wer auf Ihrer Seite hat sie zuletzt gelesen?', 'Who on your side has read them recently?', null, null, null, null, true, false, false, '[]'::jsonb, '{}'::jsonb, '[{"key":"legal_pages","values":["reuse"]}]'::jsonb, true),
  ('legal_extras', 'access_legal', 60, 'checkboxes', 'Brauchen Sie außerdem AGB, eine Widerrufsbelehrung oder einen AV-Vertrag?', 'Do you also need AGB, a cancellation policy or a DPA?', null, null, null, null, false, false, false, '[{"value":"agb","label_de":"AGB","label_en":"Terms and conditions (AGB)"},{"value":"withdrawal","label_de":"Widerrufsbelehrung","label_en":"Cancellation policy"},{"value":"dpa","label_de":"AV-Vertrag (DPA)","label_en":"Data processing agreement (DPA)"},{"value":"none","label_de":"Nichts davon","label_en":"None of these"}]'::jsonb, '{"exclusive":["none"]}'::jsonb, '[]'::jsonb, true),
