insert into onb_followups (id, sort, trigger, question_de, question_en, quick_replies, writes_to, mode, raises, active) values
  ('fu_legal_pages_unsure', 10, '{"field":"legal_pages","when":"equals","value":"unsure"}'::jsonb, 'Bei den Rechtsseiten waren Sie sich nicht sicher: Dürfen wir Ihre aktuellen Rechtsseiten übernehmen – oder haben Sie noch keine?', 'You weren''t sure about the legal pages: are you happy for us to use your current legal pages, or don''t you have any?', '[{"value":"reuse","label_de":"Die aktuellen übernehmen","label_en":"Use the current ones"},{"value":"none","label_de":"Wir haben keine","label_en":"Don''t have any"},{"value":"unsure","label_de":"Weiß ich nicht","label_en":"Not sure"}]'::jsonb, 'legal_pages', 'set', null, true),
  ('fu_legal_pages_offer', 20, '{"field":"legal_pages","when":"equals","value":"none"}'::jsonb, 'Kein Problem – wir setzen zunächst Platzhalter ein. Impressum und Datenschutzerklärung sind gesetzlich vorgeschrieben, und wir können sie für Sie erstellen. Sollen wir Ihnen dazu ein Angebot schicken?', 'No problem — we''ll put a placeholder in. These pages are required by law, and we can take care of them for you. Shall we send you a price?', '[{"value":"yes","label_de":"Ja, gerne","label_en":"Yes please"},{"value":"no","label_de":"Nein, danke","label_en":"No thanks"}]'::jsonb, null, 'set', '{"yes":{"code":"interest","detail":"legal_pages"}}'::jsonb, true),
  ('fu_crm_name', 30, '{"field":"crm_name","when":"empty"}'::jsonb, 'Welches CRM nutzen Sie?', 'Which CRM do you use?', '[{"value":"HubSpot","label_de":"HubSpot","label_en":"HubSpot"},{"value":"Salesforce","label_de":"Salesforce","label_en":"Salesforce"},{"value":"Pipedrive","label_de":"Pipedrive","label_en":"Pipedrive"}]'::jsonb, 'crm_name', 'set', null, true),
  ('fu_maps_link', 40, '{"field":"maps_link","when":"empty"}'::jsonb, 'Können Sie den Link zu Ihrem Standort auf Google Maps einfügen?', 'Can you paste the link to your location on Google Maps?', '[]'::jsonb, 'maps_link', 'set', null, true),
  ('fu_page_list_thin', 50, '{"field":"page_list","when":"lt_lines","value":3}'::jsonb, 'Sie haben nur wenige Seiten aufgeführt. Soll jede Leistung bzw. jedes Produkt eine eigene Seite bekommen?', 'You''ve listed only a few pages. Should each service or product have its own page?', '[{"value":"yes","label_de":"Ja","label_en":"Yes"},{"value":"no","label_de":"Nein","label_en":"No"},{"value":"unsure","label_de":"Weiß ich nicht","label_en":"Not sure"}]'::jsonb, 'page_relationships', 'append', null, true),
  ('fu_reference_likes', 60, '{"field":"references","when":"lt_chars","value":15,"sub":"likes"}'::jsonb, 'Was genau gefällt Ihnen an dieser Referenzseite – der Aufbau, die Farben, die Art, wie sie geschrieben ist?', 'What is it about that reference site you like — the layout, the colours, the way it is written?', '[]'::jsonb, 'references', 'set', null, true),
  ('fu_dont_know', 70, '{"when":"dont_know"}'::jsonb, 'Bei „{label}“ haben Sie „Weiß ich nicht“ gewählt. Können Sie inzwischen etwas dazu sagen? Sonst überspringen Sie die Frage einfach – wir kommen darauf zurück.', 'You chose "not sure" for "{label}". Can you say anything about it now? If not, just skip it — we will come back to it.', '[]'::jsonb, null, 'set', null, true),
  ('fu_scope_flag', 80, '{"when":"flag","flag":"scope_flag"}'::jsonb, 'Sie haben mehr Seiten aufgeführt, als Ihr Angebot umfasst. Wir melden uns dazu bei Ihnen – Sie müssen jetzt nichts tun.', 'You''ve listed more pages than your quote covers. We''ll come back to you on that — nothing to do now.', '[{"value":"ok","label_de":"Verstanden","label_en":"Understood"}]'::jsonb, null, 'acknowledge', null, true),
  ('fu_date_conflict', 90, '{"when":"flag","flag":"date_conflict"}'::jsonb, 'Zwischen Ihrem Liefertermin für Texte und Fotos und dem gewünschten Start bleibt weniger Zeit als üblich für den Bau. Was ist für Sie wichtiger?', 'There is less time than usual for the build between your content date and the launch date you want. Which matters more to you?', '[{"value":"launch_fixed","label_de":"Der Starttermin steht fest","label_en":"The launch date is fixed"},{"value":"content_earlier","label_de":"Inhalte können früher kommen","label_en":"Content can come earlier"},{"value":"unsure","label_de":"Weiß ich nicht","label_en":"Not sure"}]'::jsonb, null, 'set', null, true)
on conflict (id) do nothing;

