  ('flag_member_area', 'needs_quote', 'member_area', 'sales', '[{"key":"private_content","values":["yes"]}]'::jsonb, 'Mitglieder-/Login-Bereich gewünscht – nicht im Katalog, Angebot durch Thorsten.', 'Member / login area requested — not in the catalogue, quote via Thorsten.', 10, true),
  ('flag_social_embed', 'needs_quote', 'social_embed', 'sales', '[{"key":"social_display","values":["embedded"]}]'::jsonb, 'Social-Feed eingebettet – kostenpflichtiges Extra.', 'Embedded social feed — paid extra.', 20, true),
  ('flag_logo_redraw', 'needs_quote', 'logo_redraw', 'sales', '[{"key":"logo_vector","values":["no"]}]'::jsonb, 'Logo liegt nicht als Vektor vor – Nachzeichnen anbieten.', 'Logo not available as vector — offer a redraw.', 30, true),
