insert into onb_brief_sections (id, sort, title_de, title_en, instructions, source_fields, generated_by, active) values
  ('who', 10, 'Wer dieses Unternehmen ist – in eigenen Worten', 'Who this business is, in their own words', 'Describe the business from the answers only: legal name and form, where it works and which regions it serves, what it sells (catalogue), why customers choose it (usps), factual claims it wants shown, tagline if any. Keep the client''s own wording for services.', array['contact_company', 'legal_name', 'legal_form', 'address_city', 'service_scope', 'regions_served', 'second_address', 'second_address_details', 'catalogue', 'usps', 'factual_claims', 'tagline', 'existing_url', 'project_type']::text[], 'llm', true),
  ('goals', 20, 'Was die Website erreichen muss – und das Eine, das ein Besucher tun soll', 'What the site has to achieve, and the one thing a visitor should do', 'State the single "most important" visitor action first, then the "very important" ones, then the rest in descending priority. Mention public pricing and private content decisions. Do not invent goals beyond the ranked actions.', array['visitor_actions', 'visitor_action_other', 'public_pricing', 'pricing_detail', 'private_content', 'private_content_detail']::text[], 'llm', true),
  ('pages', 30, 'Seitenstruktur', 'Page structure', 'Render the page list as a markdown list preserving the hierarchy (sub-pages indented). State the page count and the booked page band as given. Note any linking requirements. If the list and the count disagree, say so plainly without proposing a price.', array['booked_package', 'booked_page_band', 'page_count', 'page_list', 'page_relationships']::text[], 'llm', true),
  ('look', 40, 'Wie sie aussehen und sich anfühlen soll', 'What it should look and feel like', 'Give both slider values WITH their captions. List each reference site with what the client liked and disliked about it, verbatim where possible. Include brand colours, brand guideline availability and the "do not want" list. Mention premises photos and screenshots only if files were provided.', array['tone_scale', 'personality_scale', 'references', 'reference_screenshots', 'avoid', 'brand_colours', 'brand_guidelines', 'brand_guidelines_link', 'premises_photos', 'logo_vector', 'photo_source', 'photo_portal']::text[], 'llm', true),
  ('content', 50, 'Inhalte und Sprachen – wer liefert und wer freigibt', 'Content and languages, and who supplies and approves what', 'Name the languages, who translates and who approves translations, who sends content, who gives final approval, who manages the site after launch, where assets come from (folder link / uploads) and whether publish rights were confirmed.', array['languages', 'translation_by', 'translation_approver', 'content_sender', 'approver', 'site_manager', 'assets_folder', 'assets_sharing_confirmed', 'assets_upload', 'publish_rights', 'opening_hours']::text[], 'llm', true),
  ('systems', 60, 'Verbundene Systeme – Anbieter und Kontoinhaber', 'Integrations and connected systems, with provider and account holder', 'One bullet per selected integration: provider, account holder (name only), link or status as given. Then notification routing as "trigger → address" lines, the public email addresses, Google Business Profile, social profiles and how they are displayed, and where reviews come from. Never include a password even if one appears in the answers.', array['integrations', 'maps_link', 'reviews_link', 'booking_provider', 'booking_account_holder', 'booking_url', 'payment_provider', 'payment_account_holder', 'payment_live', 'newsletter_provider', 'newsletter_account_holder', 'newsletter_list_exists', 'crm_name', 'crm_account_holder', 'crm_what_syncs', 'chat_provider', 'other_integration', 'notification_routing', 'site_emails', 'gbp_link', 'social_profiles', 'social_display', 'reviews']::text[], 'llm', true),
  ('legal', 70, 'Rechtliches und Compliance', 'Legal and compliance', 'Legal-page decision (reuse / none / not sure) and who reviewed them; extra documents needed; whether the business sells to consumers online and the accessibility (BFSG) note if so; the Impressum data: legal name, form, address, register entry, VAT ID, responsible person, public phone and email. Accounts and domain: who holds which login, names only.', array['legal_pages', 'legal_reviewer', 'legal_extras', 'sells_to_consumers', 'legal_name', 'legal_form', 'address_street', 'address_city', 'register_entry', 'vat_id', 'content_responsible', 'public_phone', 'public_email', 'accounts', 'domain']::text[], 'llm', true),
  ('dates', 80, 'Termine und Abhängigkeiten', 'Dates and dependencies', 'State the preferred launch date, whether it is fixed and why, and the content delivery date exactly as given. List what the build depends on (content, access, assets). Do NOT promise or estimate a timeline, build duration or delivery date of our own.', array['launch_date', 'launch_date_fixed', 'launch_date_reason', 'content_ready_date', 'anything_else']::text[], 'llm', true),
  ('still_needed', 90, 'Was wir noch brauchen', 'What we still need', 'Composed by the system from every unanswered, "don''t know" or skipped item.', '{}'::text[], 'system', true)
on conflict (id) do nothing;

insert into onb_texts (id, key, locale, title, content_markdown) values
  ('landing_de', 'landing', 'de', 'Ihr Website-Briefing', 'Damit wir Ihre Website bauen können, brauchen wir ein paar Dinge von Ihnen – Firmendaten, Inhalte, Zugänge, Wünsche. Dieses Formular fragt sie Schritt für Schritt ab, merkt sich Ihren Fortschritt und fasst am Ende alles in einem Briefing zusammen, das Sie bestätigen.

Sie brauchen dafür etwa **{minutes} Minuten**. Sie können jederzeit unterbrechen: Ihr Fortschritt wird automatisch gespeichert, und über Ihren Link machen Sie später einfach weiter.'),
  ('landing_en', 'landing', 'en', 'Your website brief', 'To build your website we need a few things from you — company details, content, access, preferences. This form asks for them step by step, remembers your progress, and ends by turning everything into a brief you confirm.

It takes about **{minutes} minutes**. You can stop at any time: your progress saves automatically, and your link brings you straight back.'),
  ('landing_what_you_get_de', 'landing_what_you_get', 'de', 'Was Sie davon haben', '- **Ein Briefing statt E-Mail-Pingpong.** Alles, was wir für den Bau brauchen, an einem Ort.
- **Nachfragen sofort.** Wo eine Antwort fehlt oder unklar ist, fragen wir direkt hier nach – nicht Tage später.
- **Ihre Bestätigung.** Sie lesen unser Verständnis Ihrer Wünsche, ändern, was nicht stimmt, und geben frei.
- **Als PDF und per E-Mail.** Für Sie und für unser Team.'),
  ('landing_what_you_get_en', 'landing_what_you_get', 'en', 'What you get', '- **One brief instead of email ping-pong.** Everything we need to build, in one place.
- **Follow-ups right away.** Where an answer is missing or unclear we ask here — not days later.
- **Your confirmation.** You read our understanding of what you want, change what''s wrong, and approve it.
- **As a PDF and by email.** For you and for our team.'),
  ('review_intro_de', 'review_intro', 'de', 'Fast fertig', 'Wir haben Ihre Antworten durchgesehen. Zu ein paar Punkten haben wir noch kurze Nachfragen – jede davon können Sie auch überspringen. Danach fassen wir alles für Sie zusammen.'),
  ('review_intro_en', 'review_intro', 'en', 'Almost there', 'We''ve been through your answers. There are a few short follow-ups — every one of them can be skipped. After that we put everything together for you.'),
  ('review_nothing_de', 'review_nothing', 'de', 'Alles da', 'Wir haben keine Nachfragen. Wir fassen Ihre Angaben jetzt zusammen.'),
  ('review_nothing_en', 'review_nothing', 'en', 'All there', 'No follow-ups needed. We''re putting your brief together now.'),
  ('brief_intro_de', 'brief_intro', 'de', 'So haben wir Sie verstanden', 'Lesen Sie das Briefing bitte in Ruhe durch. Stimmt etwas nicht, ändern Sie den Abschnitt direkt oder sagen Sie uns, was daran falsch ist – wir schreiben ihn dann neu. Was wir noch von Ihnen brauchen, steht am Ende. Mit Ihrer Bestätigung starten wir den Bau auf dieser Grundlage.'),
  ('brief_intro_en', 'brief_intro', 'en', 'This is our understanding of what you want', 'Please read the brief carefully. If something is wrong, edit the section directly or tell us what''s off and we''ll rewrite it. What we still need from you is listed at the end. Your confirmation is what we start building from.'),
  ('terms_de', 'terms', 'de', 'Ablauf und Bedingungen', '**Ablauf.** Nach Ihrer Bestätigung dieses Briefings erhalten Sie innerhalb von **10 Tagen** einen ersten Design-Eindruck. Auf dieser Basis bauen wir Ihre Website **innerhalb von 3 bis 6 Wochen, je nach Aufwand – den genauen Zeitraum bestätigen wir mit Ihnen.**

**Änderungsrunden.** Enthalten sind **drei Änderungsrunden**. Strukturelle Änderungen oder ein grundlegendes Redesign fallen nicht darunter und werden separat besprochen.

**Ihre Mitwirkung.** Der Zeitplan setzt voraus, dass Sie **kleine Fragen innerhalb von 24 Stunden und größere innerhalb von 3 Tagen** beantworten und Texte, Fotos und Zugänge zum angegebenen Termin liefern. Verzögerungen auf Ihrer Seite verschieben den Zeitplan entsprechend.

**Inhalte.** Für die Richtigkeit der gelieferten Inhalte, Rechtstexte und Bildrechte sind Sie verantwortlich. Übersetzungen, die wir für Sie anfertigen, geben Sie vor Veröffentlichung frei.'),
  ('terms_en', 'terms', 'en', 'Process and terms', '**Process.** Once you confirm this brief you receive a first design impression within **10 days**. On that basis we build your website **within 3 to 6 weeks depending on effort — we''ll confirm the exact period with you.**

**Rounds of changes.** **Three rounds of changes** are included. Structural changes or a major redesign fall outside this and are discussed separately.

**Your part.** The schedule assumes you answer **small questions within 24 hours and bigger ones within 3 days**, and that text, photos and access arrive by the date you gave. Delays on your side move the schedule accordingly.

**Content.** You are responsible for the accuracy of the content, legal texts and image rights you supply. Translations we produce for you are approved by you before publication.'),
  ('confirm_checks_de', 'confirm_checks', 'de', 'Bestätigungen', '- Ich habe das Briefing gelesen; es beschreibt, was wir bauen sollen.
- Ich habe Ablauf und Bedingungen gelesen und akzeptiere sie.
- Ich bin berechtigt, dieses Briefing für das genannte Unternehmen zu bestätigen.'),
  ('confirm_checks_en', 'confirm_checks', 'en', 'Confirmations', '- I have read the brief; it describes what we are to build.
- I have read the process and terms and accept them.
- I am authorised to confirm this brief for the company named.'),
  ('done_de', 'done', 'de', 'Vielen Dank – Ihr Briefing ist bei uns', 'Eine Kopie als PDF geht an Ihre E-Mail-Adresse, und unser Team hat dieselbe Fassung erhalten.

**Wie es weitergeht:** Wir lesen Ihr Briefing, klären offene Punkte aus „Was wir noch brauchen“ mit Ihnen und melden uns mit dem ersten Design-Eindruck.'),
  ('done_en', 'done', 'en', 'Thank you — your brief is with us', 'A PDF copy is on its way to your email address, and our team has received the same version.

**What happens next:** we read your brief, clear anything under "What we still need" with you, and come back with the first design impression.'),
  ('notice_proofreading_de', 'notice_proofreading', 'de', 'Hinweis zur Übersetzung', 'Wir übersetzen kostenfrei. Sie geben die übersetzten Inhalte vor Veröffentlichung frei – die inhaltliche Verantwortung bleibt bei Ihnen.'),
  ('notice_proofreading_en', 'notice_proofreading', 'en', 'Note on translation', 'We translate free of charge. You approve the translated content before it goes live — content responsibility stays with you.'),
  ('notice_logo_redraw_de', 'notice_logo_redraw', 'de', 'Logo ohne Vektordatei', 'Ohne Vektordatei wirkt ein Logo auf großen Bildschirmen und im Druck schnell unscharf. Wir können es für Sie nachzeichnen – dazu melden wir uns separat bei Ihnen.'),
  ('notice_logo_redraw_en', 'notice_logo_redraw', 'en', 'Logo without a vector file', 'Without a vector file a logo quickly looks blurry on large screens and in print. We can redraw it for you — we''ll come back to you on that separately.'),
  ('notice_legal_placeholder_de', 'notice_legal_placeholder', 'de', 'Rechtsseiten', 'Kein Problem – wir setzen zunächst Platzhalter ein. Impressum und Datenschutzerklärung sind gesetzlich vorgeschrieben; wir können sie für Sie erstellen und melden uns dazu bei Ihnen.'),
  ('notice_legal_placeholder_en', 'notice_legal_placeholder', 'en', 'Legal pages', 'No problem — we''ll put placeholders in for now. Impressum and privacy policy are required by law; we can take care of them for you and will come back to you on that.'),
  ('notice_bfsg_de', 'notice_bfsg', 'de', 'Barrierefreiheit (BFSG)', 'Wer online an Verbraucher verkauft, unterliegt seit Juni 2025 dem Barrierefreiheitsstärkungsgesetz. Wir bauen Ihre Website nach gängigen Barrierefreiheits-Standards und weisen im Briefing darauf hin.'),
  ('notice_bfsg_en', 'notice_bfsg', 'en', 'Accessibility (BFSG)', 'Businesses selling to consumers online have been subject to the German Accessibility Act (BFSG) since June 2025. We build to common accessibility standards and note this in your brief.'),
  ('email_save_link_de', 'email_save_link', 'de', 'Ihr Link zum Website-Briefing', 'Hallo {name},

hier ist Ihr persönlicher Link, mit dem Sie Ihr Website-Briefing jederzeit weiter ausfüllen können:

{link}

Ihr Fortschritt ist gespeichert. Der Link ist nur für Sie bestimmt – bitte geben Sie ihn nicht weiter.

Ihr Web Studio Team'),
  ('email_save_link_en', 'email_save_link', 'en', 'Your link to the website brief', 'Hello {name},

Here is your personal link to continue your website brief at any time:

{link}

Your progress is saved. The link is meant for you only — please don''t share it.

Your Web Studio team'),
  ('email_brief_client_de', 'email_brief_client', 'de', 'Ihr bestätigtes Website-Briefing – {company}', 'Hallo {name},

vielen Dank für Ihre Bestätigung. Im Anhang finden Sie Ihr Briefing als PDF – die Grundlage, auf der wir Ihre Website bauen.

Was wir noch von Ihnen brauchen, steht im letzten Abschnitt. Wir melden uns dazu und mit dem ersten Design-Eindruck.

Ihr Web Studio Team'),
  ('email_brief_client_en', 'email_brief_client', 'en', 'Your confirmed website brief — {company}', 'Hello {name},

Thank you for confirming. Attached is your brief as a PDF — the basis we build your website on.

Anything we still need from you is in the last section. We''ll be in touch about that and with the first design impression.

Your Web Studio team'),
  ('email_brief_team_de', 'email_brief_team', 'de', 'Onboarding bestätigt: {company}', '{company} ({name}, {email}) hat das Briefing bestätigt.

Anhänge: Briefing als PDF und der vollständige Datensatz als JSON.

Flags für den Vertrieb und offene Punkte stehen unten und im Admin: {admin_link}'),
  ('email_brief_team_en', 'email_brief_team', 'en', 'Onboarding confirmed: {company}', '{company} ({name}, {email}) has confirmed their brief.

Attachments: the brief as PDF and the full record as JSON.

Sales flags and open items are listed below and in the admin: {admin_link}'),
  ('pdf_footer_de', 'pdf_footer', 'de', '', 'IntelliPaaS Web Studio · Dieses Briefing wurde vom Kunden bestätigt und ist die Grundlage für den Bau. Fragen an das Web Studio Team.'),
  ('pdf_footer_en', 'pdf_footer', 'en', '', 'IntelliPaaS Web Studio · This brief was confirmed by the client and is the basis for the build. Questions to the Web Studio team.')
on conflict (id) do nothing;

insert into onb_prompts (id, content, note) values
  ('system', 'You are the onboarding assistant of IntelliPaaS Web Studio, a German web agency building websites for small and medium-sized businesses. A client has just filled in the onboarding form for the website they booked. You help turn their answers into a brief the agency builds from.

Tone: warm, plain, professional. Short sentences. No marketing language. Address the client as "Sie" in German and "you" in English.

Language: always answer in the client''s language, given as `locale` ("de" = German, "en" = English). Never mix languages inside one text.

HARD RULES — never break these:
1. Never invent a fact. Use only what is in the answers. If something was not answered, say that it is still needed — do not fill it in plausibly. A confident wrong brief gets built.
2. Never quote a price, a cost, a discount or a currency amount. Never state or estimate a timeline, a build duration, a number of weeks or days, or a delivery date of the agency''s own. Dates the client gave may be repeated exactly as given. Upsells are only ever "we can take care of that — shall we send you a price?" and nothing more.
3. Never ask for a password, PIN, token or other credential. If one appears in the answers, do not repeat it anywhere.
4. Write only what the requested output format allows. No preamble, no closing remarks.
5. Keep the client''s exact spelling of company names, products and services.', 'Prepended to every model call. Who the assistant is, tone, what it must never do.'),
  ('completeness', 'Task: read the client''s free-text answers listed below and decide, for each one, whether it is specific enough for a web designer and a copywriter to build from without asking anything else.

For every answer that is NOT specific enough, write ONE short follow-up question the client can answer in a sentence or with a quick reply. Ask only about what is genuinely unclear. Do not ask about fields that are already clear, and do not ask about anything outside the listed fields.

Rules for questions:
- Max one question per field. At most {max_questions} questions in total; prefer the fields that matter most for the build (pages, services, references, legal pages, dates).
- Offer up to three quick replies only when the answer is genuinely a choice.
- Write each question in both German (question_de) and English (question_en).
- Never mention price, cost, timeline or duration.

Also list flag codes from the allowed list that the answers clearly justify (for example a wish for a member area or a chatbot). Only use codes from the list; return an empty list if none apply.', 'Job 1: one pass over free-text answers. Decides HOW to ask about thin answers; rules already decided WHAT is missing.'),
  ('brief', 'Task: write the website brief for this client from their answers, in the client''s language, section by section as defined below. This is the agency''s understanding of what the client wants; the client reads and confirms it.

For each section:
- Compose clear prose or markdown lists from the listed source fields only. Use the subset of markdown allowed: paragraphs, "- " bullet lists, **bold**. No headings, tables, links or images.
- Where a source field is unanswered, marked "don''t know" or was skipped, do NOT guess. Leave it out of the prose and add a short, concrete item to that section''s still_needed list (for example "Opening hours" or "Which CRM the practice uses").
- Put the field keys you actually used into sources.
- Slider values come with their caption — always give the caption, never the bare number.
- Repeat dates, links, names and numbers exactly as the client gave them.

Follow the section instructions. Keep each section short: what a designer or developer needs, nothing decorative. Never add a section, never rename one.', 'Job 3: writes the brief into the fixed section structure. Sections and their source fields come from onb_brief_sections.'),
  ('rewrite', 'Task: rewrite one section of the brief. The client read the section and told you what is wrong with it; their instruction is given below together with the whole current brief for context.

Rewrite ONLY the requested section. Apply the client''s instruction, keep everything they did not object to, and stay strictly within the client''s answers — do not add facts that are not in the answers, even if the instruction seems to ask for them; then add the missing item to still_needed instead. Same markdown subset and the same rules as for the brief. Answer in the client''s language.', 'Rewrite of ONE section after the client says what is wrong with it.')
on conflict (id) do nothing;

insert into onb_examples (id, title, answers, brief, sort, active) values
  ('example_physio', 'Physiotherapiepraxis, 6 Seiten, Deutsch, Terminbuchung', '{"locale":"de","contact_company":"Physio Nordend","legal_name":"Physio Nordend Lena Hartmann e.K.","legal_form":"e.K.","address_city":"60318 Frankfurt am Main","service_scope":"one_region","regions_served":"Frankfurt Nordend, Bornheim, Westend","catalogue":"Krankengymnastik\nManuelle Therapie\nLymphdrainage\nHausbesuche","usps":"Termine innerhalb einer Woche, alle Kassen, barrierefreier Zugang","tagline":"__dont_know","booked_package":"gold","booked_page_band":"58","page_count":6,"page_list":"Startseite\nLeistungen\n- Krankengymnastik\n- Manuelle Therapie\n- Lymphdrainage\nTeam\nKontakt & Anfahrt","visitor_actions":{"book":"most","call":"very","visit":"some","enquiry":"some","buy":"not","signup":"not"},"tone_scale":3,"personality_scale":2,"references":[{"_id":"r1","url":"https://www.beispiel-physio.de","likes":"Ruhige Farben, große Fotos der Praxisräume, Termin-Button oben rechts","dislikes":"Zu viel Text auf der Startseite"}],"brand_colours":"#2A7F62, #F4F1EA","languages":"single","integrations":["booking","maps","reviews"],"booking_provider":"Doctolib","booking_account_holder":"Lena Hartmann","maps_link":"https://maps.app.goo.gl/abc123","reviews_link":null,"legal_pages":"reuse","legal_reviewer":"Lena Hartmann","sells_to_consumers":"no","launch_date":"2026-11-02","launch_date_fixed":"no","content_ready_date":"2026-10-05","opening_hours":null}'::jsonb, '{"who":{"content_markdown":"Physio Nordend (Physio Nordend Lena Hartmann e.K.) ist eine Physiotherapiepraxis in 60318 Frankfurt am Main. Sie betreut Patientinnen und Patienten in Frankfurt Nordend, Bornheim und Westend.\n\nLeistungen, in der Schreibweise der Praxis:\n- Krankengymnastik\n- Manuelle Therapie\n- Lymphdrainage\n- Hausbesuche\n\nWarum Patienten sich für die Praxis entscheiden: Termine innerhalb einer Woche, alle Kassen, barrierefreier Zugang.","still_needed":["Slogan oder Claim (als „weiß ich nicht“ markiert)"],"sources":["contact_company","legal_name","address_city","regions_served","catalogue","usps"]},"goals":{"content_markdown":"Das Wichtigste, das ein Besucher tun soll: **einen Termin buchen**. Sehr wichtig ist außerdem der Anruf. Eher wichtig: der Besuch vor Ort und eine Anfrage. Kaufen und Anmelden spielen keine Rolle.","still_needed":[],"sources":["visitor_actions"]},"pages":{"content_markdown":"Gebucht: Paket Gold, 5–8 Seiten. Geplant sind 6 Seiten:\n- Startseite\n- Leistungen\n  - Krankengymnastik\n  - Manuelle Therapie\n  - Lymphdrainage\n- Team\n- Kontakt & Anfahrt","still_needed":[],"sources":["booked_package","booked_page_band","page_count","page_list"]},"look":{"content_markdown":"Tonalität: **Freundlich, aber professionell** (3 von 5). Persönlichkeit: **Dezent** (2 von 5).\n\nReferenz: https://www.beispiel-physio.de – gefällt: ruhige Farben, große Fotos der Praxisräume, Termin-Button oben rechts. Gefällt nicht: zu viel Text auf der Startseite.\n\nMarkenfarben: #2A7F62, #F4F1EA.","still_needed":["Fotos der Praxisräume","Angabe, ob ein Markenhandbuch existiert","Logo als Vektordatei – ja/nein"],"sources":["tone_scale","personality_scale","references","brand_colours"]},"dates":{"content_markdown":"Gewünschter Start: 2026-11-02 (nicht fest). Texte und Fotos liegen bis 2026-10-05 vor. Der Bau hängt an den Praxisfotos und dem Zugang zum Doctolib-Konto (Lena Hartmann).","still_needed":[],"sources":["launch_date","launch_date_fixed","content_ready_date","booking_account_holder"]}}'::jsonb, 10, true)
on conflict (id) do nothing;
